 341.84)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">10</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"336.96562500000005\" x2=\"336.96562500000005\" y1=\"72\" y2=\"322\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"middle\" transform=\"translate(336.96562500000005 341.84)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">14</text><text text-anchor=\"middle\" transform=\"translate(224.828125 24)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Average Survival of Fruit Flies </text><text text-anchor=\"middle\" transform=\"translate(224.828125 48)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">following Infection</text><text text-anchor=\"middle\" transform=\"translate(224.828125 375.67999999999995)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Days after infection</text><rect xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" x=\"107.23628997802734\" y=\"392.84000000000003\" height=\"103\" width=\"180.5274200439453\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><line x1=\"114.23628997802734\" y1=\"409.84000000000003\" x2=\"141.23628997802734\" y2=\"409.84000000000003\" stroke=\"#000\" stroke-width=\"2.4\" marker-end=\"url(#marker0)\"/><line x1=\"141.23628997802734\" y1=\"409.84000000000003\" x2=\"168.23628997802734\" y2=\"409.84000000000003\" stroke=\"#000\" stroke-width=\"2.4\" marker-start=\"url(#marker0)\"/><text transform=\"translate(178.23628997802734 416.84000000000003)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> type A flies</text><line x1=\"114.23628997802734\" y1=\"441.84000000000003\" x2=\"141.23628997802734\" y2=\"441.84000000000003\" stroke=\"#000\" stroke-width=\"2.4\" stroke-dasharray=\"9 6\" marker-end=\"url(#marker1)\"/><line x1=\"141.23628997802734\" y1=\"441.84000000000003\" x2=\"168.23628997802734\" y2=\"441.84000000000003\" stroke=\"#000\" stroke-width=\"2.4\" stroke-dasharray=\"9 6\" marker-start=\"url(#marker1)\"/><text transform=\"translate(178.23628997802734 448.84000000000003)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> type AB flies</text><line x1=\"114.23628997802734\" y1=\"473.84000000000003\" x2=\"141.23628997802734\" y2=\"473.84000000000003\" stroke=\"#000\" stroke-width=\"3\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" marker-end=\"url(#marker2)\"/><line x1=\"141.23628997802734\" y1=\"473.84000000000003\" x2=\"168.23628997802734\" y2=\"473.84000000000003\" stroke=\"#000\" stroke-width=\"3\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" marker-start=\"url(#marker2)\"/><text transform=\"translate(178.23628997802734 480.84000000000003)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> type B flies</text><line x1=\"112.690625\" y1=\"94.72727272727275\" x2=\"168.759375\" y2=\"94.72727272727275\" stroke=\"#000\" stroke-width=\"2.4\" marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\"/><line x1=\"112.690625\" y1=\"94.72727272727275\" x2=\"168.759375\" y2=\"99.27272727272728\" stroke=\"#000\" stroke-width=\"2.4\" stroke-dasharray=\"9 6\" marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\"/><line x1=\"112.690625\" y1=\"94.72727272727275\" x2=\"168.759375\" y2=\"103.81818181818184\" stroke=\"#000\" stroke-width=\"3\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\"/><line x1=\"168.759375\" y1=\"94.72727272727275\" x2=\"224.828125\" y2=\"103.81818181818184\" stroke=\"#000\" stroke-width=\"2.4\" marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\"/><line x1=\"168.759375\" y1=\"99.27272727272728\" x2=\"224.828125\" y2=\"217.45454545454547\" stroke=\"#000\" stroke-width=\"2.4\" stroke-dasharray=\"9 6\" marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\"/><line x1=\"168.759375\" y1=\"103.81818181818184\" x2=\"224.828125\" y2=\"228.8181818181818\" stroke=\"#000\" stroke-width=\"3\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\"/><line x1=\"224.828125\" y1=\"103.81818181818184\" x2=\"280.896875\" y2=\"112.90909090909093\" stroke=\"#000\" stroke-width=\"2.4\" marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\"/><line x1=\"224.828125\" y1=\"217.45454545454547\" x2=\"280.896875\" y2=\"294.72727272727275\" stroke=\"#000\" stroke-width=\"2.4\" stroke-dasharray=\"9 6\" marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\"/><line x1=\"224.828125\" y1=\"228.8181818181818\" x2=\"280.896875\" y2=\"312.90909090909093\" stroke=\"#000\" stroke-width=\"3\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\"/><line x1=\"280.896875\" y1=\"112.90909090909093\" x2=\"336.96562500000005\" y2=\"117.45454545454544\" stroke=\"#000\" stroke-width=\"2.4\" marker-end=\"url(#marker0)\" marker-start=\"url(#marker0)\"/><line x1=\"280.896875\" y1=\"294.72727272727275\" x2=\"336.96562500000005\" y2=\"322\" stroke=\"#000\" stroke-width=\"2.4\" stroke-dasharray=\"9 6\" marker-end=\"url(#marker1)\" marker-start=\"url(#marker1)\"/><line x1=\"280.896875\" y1=\"312.90909090909093\" x2=\"336.96562500000005\" y2=\"322\" stroke=\"#000\" stroke-width=\"3\" stroke-dasharray=\"1.1 6\" stroke-linecap=\"round\" marker-end=\"url(#marker2)\" marker-start=\"url(#marker2)\"/></g></svg></figure><div class=\"sr-only\" role=\"region\" aria-label=\"Long description for line graph titled Average Survival of Fruit Flies following Infection\"><ul>\n<li>The following 3 lines are shown:<br/>\n<ul>\n<li>type A flies</li>\n<li>type AB flies</li>\n<li>type B flies</li>\n</ul>\n</li>\n<li>The type A flies line:<br/>\n<ul>\n<li>Begins at 0 days, 100%</li>\n<li>Remains level to 2 days after infection, 100%</li>\n<li>Falls gradually to 6 days after infection, 96%</li>\n<li>Falls gradually to 10 days after infection, 92%</li>\n<li>Falls gradually to 14 days after infection, 90%</li>\n</ul>\n</li>\n<li>The type AB flies line:&nbsp;<br/>\n<ul>\n<li>Begins at 0 days after infection, 100%</li>\n<li>Falls gradually to 2 days after infection, 98%</li>\n<li>Falls sharply to 6 days after infection, 46%</li>\n<li>Falls sharply to 10 days after infection, 12%</li>\n<li>Falls sharply to 14 days after infection, 0%</li>\n</ul>\n</li>\n<li>The type B flies line:&nbsp;<br/>\n<ul>\n<li>Begins at 0 days after infection, 100%</li>\n<li>Falls gradually to 2 days after infection, 96%</li>\n<li>Falls sharply to 6 days after infection, 41%</li>\n<li>Falls sharply to 10 days after infection, 4%</li>\n<li>Falls gradually to 14 days after infection, 0%</li>\n</ul>\n</li>\n</ul></div>\n<p>In a study of the evolution of <em>DptA</em>&nbsp;and&nbsp;<em>DptB</em>&mdash;<em>Diptericin</em>&nbsp;genes encoding antimicrobial peptides that combat pathogens and foster beneficial microbes in fruit flies (<em>Drosophila</em>)&mdash;researchers assessed <em>Drosophila melanogaster</em> resistance to pathogenic infections by <em>Providencia rettgeri</em>&nbsp;and&nbsp;<em>Acetobacter</em> <em>sicerae</em>, bacteria common in the flies&rsquo; environments. Subjects included flies identified by mutations silencing <em>DptA</em>,&nbsp;<em>DptB</em>, or both&nbsp;<em>DptA</em>&nbsp;and&nbsp;<em>DptB</em> (termed types A, B, and <span data-ssml-say-as=\"characters\">AB</span>, respectively). In conjunction with the observation that resistance to <em><span data-ssml-sub-alias=\"P\">P.</span> rettgeri</em>&nbsp;correlates with&nbsp;<em>DptA</em>&nbsp;activity but is not significantly affected by&nbsp;<em>DptB</em> activity, data in the graph of survival rates post&ndash;<em><span data-ssml-sub-alias=\"A\">A.</span> sicerae</em> infection suggest that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which completion of the text is best supported by data in the graph?</p>","answerOptions":[{"id":"4a6a6a40-ed7c-4ca1-b261-4591872c787a","content":"<p><em>DptA</em> confers defense against <em><span data-ssml-sub-alias=\"A\">A.</span> sicerae</em> regardless of the presence of <em>DptB</em>.</p>"},{"id":"7d90f521-b1ad-46cc-a38e-82888b447cd9","content":"<p><em>DptB</em> protects against only one bacteria species, whereas <em>DptA</em> protects against multiple species.</p>"},{"id":"1d0f5e66-12c3-4ce3-8b5b-6bc44f9beb8a","content":"<p><em>DptB</em> may have developed as a specific defense against <em><span data-ssml-sub-alias=\"A\">A.</span> sicerae</em>.</p>"},{"id":"64281b76-a8eb-4797-b2d9-4d918d3a6bea","content":"<p>defense against <em><span data-ssml-sub-alias=\"A\">A.</span> sicerae</em> is strongest when both <em>DptA</em> and <em>DptB</em> are present.</p>"}],"keys":["1d0f5e66-12c3-4ce3-8b5b-6bc44f9beb8a"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text based on supporting data in the graph. The text indicates that in the fly <em>D. melanogaster</em>, <em>DptA</em> and <em>DptB</em> are genes that encode peptides that both fight pathogens and promote beneficial microbes. Researchers tested <em>D. melanogaster</em>&rsquo;s resistance to <em>P. rettgeri</em> and <em>A. sicerae</em> bacteria based on which variation of the peptide-encoding gene the flies exhibit: <em>DptA</em> silenced (referred to as type A), <em>DptB</em> silenced (type B), or both silenced (type AB). The text also indicates that resistance to <em>P. rettgeri</em> correlates with <em>DptA</em> activity but not with <em>DptB</em> activity (which would manifest as type B flies surviving at a higher rate than other fly types when exposed to <em>P. rettgeri</em>). The graph shows the post&ndash;<em>A. sicerae</em> infection results, which indicate that <em>DptB</em> activity was most strongly associated with survival, whereas <em>DptA</em> activity was not (manifesting in the graph as the type A flies having greater survival rates than the other fly types). In other words, when <em>DptA</em> activity was silenced, the flies showed relatively high survival rates, but when <em>DptB</em> activity was silenced, whether on its own or in conjunction with <em>DptA</em> activity being silenced, survival rates were low, suggesting that <em>DptB</em> may have developed as a specific defense against <em>A. sicerae</em>.</p><p>Choice A is incorrect. The graph suggests that <em>DptA</em> activity is associated with a low rate of survival, not a high one. Furthermore, the graph shows results for flies where <em>DptA</em> alone was silenced, <em>DptB</em> alone was silenced, and both were silenced and thus does not show any flies with activity in both <em>DptA</em> and <em>DptB</em>, which would be necessary to determine whether <em>DptA </em>conferred defense against <em>A. sicerae</em> in the presence of<em> DptB</em>. Choice B is incorrect. Only two bacteria species were considered in the text: <em>P. rettgeri</em> and <em>A. sicerae</em>. The text and graph taken together suggest that activity in <em>DptA</em> is associated with resistance to <em>P. rettgeri</em> while <em>DptB</em> activity is not, and that <em>DptB</em> activity is associated with resistance to <em>A. sicerae</em> while <em>DptA</em> is not. There is no further information to suggest one genetic type confers resistance to a greater number of pathogens than the other. Choice D is incorrect. The graph does not address flies with activity in both <em>DptA</em> and <em>DptB</em>. All flies represented in the graph had one or both of <em>DptA</em> and <em>DptB</em> silenced, or inactive.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669208,"updateDate":1743430669208}$SATQ$::jsonb, 1743430669208, 1743430669208),
    ($SATQ$cbecb873$SATQ$, $SATQ$a5984ea3-e26b-4dd5-8af4-5d9dae0b3b10$SATQ$::uuid, $SATQ$ff796cbd-09f2-443f-b016-15726e7f4ea8$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Body Length, Filter Time, and Lunges per Dive for Four Whale Species</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Whale species</th><th scope="col" style="text-align: center;vertical-align: bottom;">Typical adult body length (meters)</th><th scope="col" style="text-align: center;vertical-align: bottom;">Average time to filter all engulfed water (seconds)</th><th scope="col" style="text-align: center;vertical-align: bottom;">Average number of lunges per dive deeper than 50 meters</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">fin</th><td>18&ndash;22</td><td style="text-align: center;">31.30</td><td style="text-align: center;">3.95</td></tr><tr><th scope="row" style="text-align: left;">humpback</th><td>11&ndash;17</td><td style="text-align: center;">17.12</td><td style="text-align: center;">6.28</td></tr><tr><th scope="row" style="text-align: left;">minke</th><td>7&ndash;10</td><td style="text-align: center;">8.88</td><td style="text-align: center;">7.48</td></tr><tr><th scope="row" style="text-align: left;">blue</th><td>24&ndash;34</td><td style="text-align: center;">60.27</td><td style="text-align: center;">4.02</td></tr></tbody></table></figure></p>
<p>Some whale species practice lunge feeding, in which they lunge toward prey with their mouths open at wide angles, collect the prey and the surrounding water, and then filter out the water through baleen plates in their mouths. Although the volume of water engulfed increases with whales&rsquo; body length, the surface area of whales&rsquo; baleen plates, which influences the rate at which water can be filtered, does not increase with body length to the same degree, which helps explain why <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the statement?</p>$SATQ$, $SATQ$[{"id":"7619ffad-e59d-4817-9a76-89dfd6e03857","content":"<p>minke whales and humpback whales show similar average filter times.</p>"},{"id":"79c651f4-cacb-44ba-bd7a-bba8c71f074a","content":"<p>humpback whales show an average of 6.28 lunges per dive.</p>"},{"id":"0bdf5a54-1c07-48fa-9a6d-5460c121a8f0","content":"<p>fin whales show a longer average filter time than minke whales do.&nbsp;</p>"},{"id":"6a25ef72-e848-4556-8e63-33113b1c99b2","content":"<p>blue whales show the longest average filter time and the highest average number of lunges per dive.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["0bdf5a54-1c07-48fa-9a6d-5460c121a8f0"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. To support the claim, we need to show that longer whales take more time to filter all the water they engulf than shorter whales do. This choice accurately reflects that a longer whale (the fin whale) takes more time to filter engulfed water (31.30 seconds on average) compared to a shorter whale (the minke whale, which only took 8.88 seconds on average). </p><p>Choice A is incorrect. The table shows that minke whales take an average of 8.88 seconds to filter engulfed water, while humpback whales take an average of 17.12 seconds to complete the same task. Choice B is incorrect. This choice doesn&rsquo;t reflect the claim about baleen plates. The claim explains why whales of differing lengths take different amounts of time to filter engulfed water. This choice doesn&rsquo;t compare whales of different lengths, and it focuses on the number of lunges, which isn&rsquo;t shown to be relevant to filter time. Choice D is incorrect. The table shows that blue whales average 4.02 lunges per dive, which is not the highest average among the whales in the table. </p>$SATQ$, false, 0, $SATQ$OSP-KA-QUA-M008$SATQ$, $SATQ$$SATQ$, $SATQ$64ab37e0-757d-4911-9dbe-1229b3882bc3$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"cbecb873","external_id":"a5984ea3-e26b-4dd5-8af4-5d9dae0b3b10","vaultid":"ff796cbd-09f2-443f-b016-15726e7f4ea8","uId":"7a2da20d-f054-41ec-a6c5-40a8418f1bf2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Body Length, Filter Time, and Lunges per Dive for Four Whale Species</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Whale species</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Typical adult body length (meters)</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Average time to filter all engulfed water (seconds)</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Average number of lunges per dive deeper than 50 meters</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">fin</th><td>18&ndash;22</td><td style=\"text-align: center;\">31.30</td><td style=\"text-align: center;\">3.95</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">humpback</th><td>11&ndash;17</td><td style=\"text-align: center;\">17.12</td><td style=\"text-align: center;\">6.28</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">minke</th><td>7&ndash;10</td><td style=\"text-align: center;\">8.88</td><td style=\"text-align: center;\">7.48</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">blue</th><td>24&ndash;34</td><td style=\"text-align: center;\">60.27</td><td style=\"text-align: center;\">4.02</td></tr></tbody></table></figure></p>\n<p>Some whale species practice lunge feeding, in which they lunge toward prey with their mouths open at wide angles, collect the prey and the surrounding water, and then filter out the water through baleen plates in their mouths. Although the volume of water engulfed increases with whales&rsquo; body length, the surface area of whales&rsquo; baleen plates, which influences the rate at which water can be filtered, does not increase with body length to the same degree, which helps explain why <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the statement?</p>","answerOptions":[{"id":"7619ffad-e59d-4817-9a76-89dfd6e03857","content":"<p>minke whales and humpback whales show similar average filter times.</p>"},{"id":"79c651f4-cacb-44ba-bd7a-bba8c71f074a","content":"<p>humpback whales show an average of 6.28 lunges per dive.</p>"},{"id":"0bdf5a54-1c07-48fa-9a6d-5460c121a8f0","content":"<p>fin whales show a longer average filter time than minke whales do.&nbsp;</p>"},{"id":"6a25ef72-e848-4556-8e63-33113b1c99b2","content":"<p>blue whales show the longest average filter time and the highest average number of lunges per dive.&nbsp;</p>"}],"keys":["0bdf5a54-1c07-48fa-9a6d-5460c121a8f0"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. To support the claim, we need to show that longer whales take more time to filter all the water they engulf than shorter whales do. This choice accurately reflects that a longer whale (the fin whale) takes more time to filter engulfed water (31.30 seconds on average) compared to a shorter whale (the minke whale, which only took 8.88 seconds on average). </p><p>Choice A is incorrect. The table shows that minke whales take an average of 8.88 seconds to filter engulfed water, while humpback whales take an average of 17.12 seconds to complete the same task. Choice B is incorrect. This choice doesn&rsquo;t reflect the claim about baleen plates. The claim explains why whales of differing lengths take different amounts of time to filter engulfed water. This choice doesn&rsquo;t compare whales of different lengths, and it focuses on the number of lunges, which isn&rsquo;t shown to be relevant to filter time. Choice D is incorrect. The table shows that blue whales average 4.02 lunges per dive, which is not the highest average among the whales in the table. </p>","parenttemplatename":"OSP-KA-QUA-M008","parenttemplateid":"","templateclusterid":"64ab37e0-757d-4911-9dbe-1229b3882bc3","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959371,"updateDate":1691007959371}$SATQ$::jsonb, 1691007959371, 1691007959371),
    ($SATQ$cca6fae9$SATQ$, $SATQ$23b0f654-fb5e-48f3-8739-811562c9bf99$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Delta 15-N Values in Seagrass Samples from Four Sites on the Yucatan, 2016–2017</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Site</th><th scope="col" style="text-align: center;vertical-align: bottom;">February 2016</th><th scope="col" style="text-align: center;vertical-align: bottom;">October 2016</th><th scope="col" style="text-align: center;vertical-align: bottom;">February 2017</th><th scope="col" style="text-align: center;vertical-align: bottom;">October 2017</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">Akumal Bay</th><td>no data available</td><td style="text-align: center;">3.3</td><td style="text-align: center;">2.0</td><td style="text-align: center;">6.3</td></tr><tr><th scope="row" style="text-align: left;">Mahahual</th><td style="text-align: center;">0.7</td><td>no data available</td><td style="text-align: center;">2.5</td><td style="text-align: center;">3.4</td></tr><tr><th scope="row" style="text-align: left;">Tulum</th><td style="text-align: center;">6.1</td><td style="text-align: center;">5.9</td><td style="text-align: center;">2.3</td><td style="text-align: center;">5.5</td></tr><tr><th scope="row" style="text-align: left;">Xahuayxol</th><td style="text-align: center;">0.9</td><td style="text-align: center;">0.3</td><td style="text-align: center;">&minus;0.9</td><td style="text-align: center;">1.4</td></tr></tbody></table></figure></p>
<p>Because water from natural, uncontaminated sources is less enriched with the stable nitrogen isotope <sup>15</sup>N than wastewater from human activities is, the presence of such wastewater in nature can be detected by examining delta 15-N values (a measure of the ratio of <sup>15</sup>N to <sup>14</sup>N) in plants. Karla A. Camacho-Cruz and colleagues assessed delta 15-N values in the seagrass <em>Thalassia testudinum</em> from sites on Mexico&rsquo;s Yucatan peninsula with intermediate tourism development, including Akumal Bay and Tulum, and low tourism development, including Mahahual and Xahuayxol, throughout 2016 and 2017. The data suggest that the intermediate-tourism sites experienced influxes of human wastewater. <span style="text-decoration: underline;" role="region" aria-label="Referenced Content">However, the researchers concluded that this happened intermittently.</span></p>$SATQ$, $SATQ$<p>Which choice best describes data from the table that support the underlined conclusion?</p>$SATQ$, $SATQ$[{"id":"814d2cd7-49de-4e18-8fc4-3670264bb13b","content":"<p>Although delta 15-N values were generally higher in Akumal Bay and Tulum than in Mahahual and Xahuayxol, the values were lower in Akumal Bay than in Mahahual and Xahuayxol in February 2017.</p>"},{"id":"bedff170-a029-42e3-8c14-5ae058071eb2","content":"<p>Delta 15-N values reached their lowest level in February 2017 in both Akumal Bay and Tulum, but no data were available for Akumal Bay in February 2016, when the values reached their highest level in Tulum.</p>"},{"id":"e1f353e1-43f7-408c-8838-d8c720e48902","content":"<p>Although all sites showed considerable variation in delta 15-N values, the values remained relatively constant in Akumal Bay from October 2016 to February 2017 and in Tulum from February 2016 to October 2016.</p>"},{"id":"cf5b7df2-2fa1-431d-bda3-9c19563201f6","content":"<p>In Akumal Bay and Tulum, delta 15-N values fluctuated considerably across the three measurements made from October 2016 to October 2017.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["cf5b7df2-2fa1-431d-bda3-9c19563201f6"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it describes data from the table that support the underlined conclusion. The text accompanying the table states that delta 15-N values (a measure of the ratio of two nitrogen isotopes) can be used as an indirect means of measuring the ratio of human wastewater to water from uncontaminated sources&mdash;the higher the delta 15-N values, the greater the presence of human wastewater. The text goes on to mention an experiment conducted by Camacho-Cruz and colleagues measuring delta 15-N values in seagrass on the Yucatan peninsula at several sites, four of which are presented in the table accompanying the text. Two of the sites noted in the table, Akumal Bay and Tulum, had intermediate tourism development, and two others, Mahahual and Xahuayxol, had low tourism development. It is reasonable to infer that sites with intermediate tourism have a greater human presence than those with low tourism and therefore are subject to greater amounts of wastewater and exhibit higher delta 15-N values in seagrass. However, Camacho-Cruz and colleagues found that the increase in delta 15-N values was not constant. The table supports this conclusion because the two intermediate-tourism sites (Akumal Bay and Tulum) had delta 15-N values that fluctuated considerably&mdash;both had higher delta 15-N values than the two low-tourism sites (Mahahual and Xahuayxol) in October 2016 and October 2017, but in February 2017 the delta 15-N values for the intermediate-tourism sites dropped significantly (in fact, Mahahual, a low-tourism site, had a higher delta 15-N value for that period). The fluctuations in values in Akumal Bay and Tulum support the conclusion that these sites experienced influxes of human wastewater intermittently.</p><p>Choice A is incorrect because it inaccurately describes data from the table: in February 2017 the delta 15-N value in Akumal Bay was higher than the delta 15-N value in Xahuayxol, not lower. Choice B is incorrect because the absence of data for delta 15-N levels in Akumal Bay in February 2016 would neither prove nor disprove that the presence of human wastewater at Akumal Bay and Tulum was not constant. Despite the unavailable data, there is still enough information to conclude that delta 15-N levels at both sites fluctuated significantly and that influxes of human wastewater therefore happened intermittently. Choice C is incorrect because a constancy in delta 15-N values would not indicate that the influx of human wastewater was intermittent, but rather the opposite. Moreover, the two periods selected are not indicative of general trends in the whole table (for example, the values fluctuated significantly in Akumal Bay between February 2017 and October 2017, and in Tulum between October 2016 and February 2017).</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"cca6fae9","external_id":"23b0f654-fb5e-48f3-8739-811562c9bf99","vaultid":null,"uId":"c0c3e9dc-b6a5-4a69-8fd8-795d713505e6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Delta 15-N Values in Seagrass Samples from Four Sites on the Yucatan, 2016–2017</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Site</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">February 2016</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">October 2016</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">February 2017</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">October 2017</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">Akumal Bay</th><td>no data available</td><td style=\"text-align: center;\">3.3</td><td style=\"text-align: center;\">2.0</td><td style=\"text-align: center;\">6.3</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Mahahual</th><td style=\"text-align: center;\">0.7</td><td>no data available</td><td style=\"text-align: center;\">2.5</td><td style=\"text-align: center;\">3.4</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Tulum</th><td style=\"text-align: center;\">6.1</td><td style=\"text-align: center;\">5.9</td><td style=\"text-align: center;\">2.3</td><td style=\"text-align: center;\">5.5</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Xahuayxol</th><td style=\"text-align: center;\">0.9</td><td style=\"text-align: center;\">0.3</td><td style=\"text-align: center;\">&minus;0.9</td><td style=\"text-align: center;\">1.4</td></tr></tbody></table></figure></p>\n<p>Because water from natural, uncontaminated sources is less enriched with the stable nitrogen isotope <sup>15</sup>N than wastewater from human activities is, the presence of such wastewater in nature can be detected by examining delta 15-N values (a measure of the ratio of <sup>15</sup>N to <sup>14</sup>N) in plants. Karla A. Camacho-Cruz and colleagues assessed delta 15-N values in the seagrass <em>Thalassia testudinum</em> from sites on Mexico&rsquo;s Yucatan peninsula with intermediate tourism development, including Akumal Bay and Tulum, and low tourism development, including Mahahual and Xahuayxol, throughout 2016 and 2017. The data suggest that the intermediate-tourism sites experienced influxes of human wastewater. <span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">However, the researchers concluded that this happened intermittently.</span></p>","stem":"<p>Which choice best describes data from the table that support the underlined conclusion?</p>","answerOptions":[{"id":"814d2cd7-49de-4e18-8fc4-3670264bb13b","content":"<p>Although delta 15-N values were generally higher in Akumal Bay and Tulum than in Mahahual and Xahuayxol, the values were lower in Akumal Bay than in Mahahual and Xahuayxol in February 2017.</p>"},{"id":"bedff170-a029-42e3-8c14-5ae058071eb2","content":"<p>Delta 15-N values reached their lowest level in February 2017 in both Akumal Bay and Tulum, but no data were available for Akumal Bay in February 2016, when the values reached their highest level in Tulum.</p>"},{"id":"e1f353e1-43f7-408c-8838-d8c720e48902","content":"<p>Although all sites showed considerable variation in delta 15-N values, the values remained relatively constant in Akumal Bay from October 2016 to February 2017 and in Tulum from February 2016 to October 2016.</p>"},{"id":"cf5b7df2-2fa1-431d-bda3-9c19563201f6","content":"<p>In Akumal Bay and Tulum, delta 15-N values fluctuated considerably across the three measurements made from October 2016 to October 2017.</p>"}],"keys":["cf5b7df2-2fa1-431d-bda3-9c19563201f6"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it describes data from the table that support the underlined conclusion. The text accompanying the table states that delta 15-N values (a measure of the ratio of two nitrogen isotopes) can be used as an indirect means of measuring the ratio of human wastewater to water from uncontaminated sources&mdash;the higher the delta 15-N values, the greater the presence of human wastewater. The text goes on to mention an experiment conducted by Camacho-Cruz and colleagues measuring delta 15-N values in seagrass on the Yucatan peninsula at several sites, four of which are presented in the table accompanying the text. Two of the sites noted in the table, Akumal Bay and Tulum, had intermediate tourism development, and two others, Mahahual and Xahuayxol, had low tourism development. It is reasonable to infer that sites with intermediate tourism have a greater human presence than those with low tourism and therefore are subject to greater amounts of wastewater and exhibit higher delta 15-N values in seagrass. However, Camacho-Cruz and colleagues found that the increase in delta 15-N values was not constant. The table supports this conclusion because the two intermediate-tourism sites (Akumal Bay and Tulum) had delta 15-N values that fluctuated considerably&mdash;both had higher delta 15-N values than the two low-tourism sites (Mahahual and Xahuayxol) in October 2016 and October 2017, but in February 2017 the delta 15-N values for the intermediate-tourism sites dropped significantly (in fact, Mahahual, a low-tourism site, had a higher delta 15-N value for that period). The fluctuations in values in Akumal Bay and Tulum support the conclusion that these sites experienced influxes of human wastewater intermittently.</p><p>Choice A is incorrect because it inaccurately describes data from the table: in February 2017 the delta 15-N value in Akumal Bay was higher than the delta 15-N value in Xahuayxol, not lower. Choice B is incorrect because the absence of data for delta 15-N levels in Akumal Bay in February 2016 would neither prove nor disprove that the presence of human wastewater at Akumal Bay and Tulum was not constant. Despite the unavailable data, there is still enough information to conclude that delta 15-N levels at both sites fluctuated significantly and that influxes of human wastewater therefore happened intermittently. Choice C is incorrect because a constancy in delta 15-N values would not indicate that the influx of human wastewater was intermittent, but rather the opposite. Moreover, the two periods selected are not indicative of general trends in the whole table (for example, the values fluctuated significantly in Akumal Bay between February 2017 and October 2017, and in Tulum between October 2016 and February 2017).</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061176,"updateDate":1755117061176}$SATQ$::jsonb, 1755117061176, 1755117061176),
