9" x1="152.703125" x2="164.703125" xmlns="http://www.w3.org/2000/svg" y1="162.66666666666666" y2="162.66666666666666"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="end" transform="translate(146.703125 168.66666666666666)">120</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="158.703125" x2="385" xmlns="http://www.w3.org/2000/svg" y1="184.88888888888889" y2="184.88888888888889"></line><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="152.703125" x2="164.703125" xmlns="http://www.w3.org/2000/svg" y1="184.88888888888889" y2="184.88888888888889"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="end" transform="translate(146.703125 190.88888888888889)">100</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="158.703125" x2="385" xmlns="http://www.w3.org/2000/svg" y1="207.11111111111111" y2="207.11111111111111"></line><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="152.703125" x2="164.703125" xmlns="http://www.w3.org/2000/svg" y1="207.11111111111111" y2="207.11111111111111"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="end" transform="translate(146.703125 213.11111111111111)">80</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="158.703125" x2="385" xmlns="http://www.w3.org/2000/svg" y1="229.33333333333331" y2="229.33333333333331"></line><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="152.703125" x2="164.703125" xmlns="http://www.w3.org/2000/svg" y1="229.33333333333331" y2="229.33333333333331"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="end" transform="translate(146.703125 235.33333333333331)">60</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="158.703125" x2="385" xmlns="http://www.w3.org/2000/svg" y1="251.55555555555554" y2="251.55555555555554"></line><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="152.703125" x2="164.703125" xmlns="http://www.w3.org/2000/svg" y1="251.55555555555554" y2="251.55555555555554"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="end" transform="translate(146.703125 257.55555555555554)">40</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="158.703125" x2="385" xmlns="http://www.w3.org/2000/svg" y1="273.77777777777777" y2="273.77777777777777"></line><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="152.703125" x2="164.703125" xmlns="http://www.w3.org/2000/svg" y1="273.77777777777777" y2="273.77777777777777"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="end" transform="translate(146.703125 279.77777777777777)">20</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="158.703125" x2="385" xmlns="http://www.w3.org/2000/svg" y1="296" y2="296"></line><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="152.703125" x2="164.703125" xmlns="http://www.w3.org/2000/svg" y1="296" y2="296"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="end" transform="translate(146.703125 302)">0</text><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(24 196) rotate(-90)">REM sleep as % of baseline </text><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(48 196) rotate(-90)">(mean difference from </text><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(72 196) rotate(-90)">baseline was not statistically</text><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(96 196) rotate(-90)">significant)</text><line fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9" x1="158.703125" x2="158.703125" xmlns="http://www.w3.org/2000/svg" y1="96" y2="296"></line><rect fill="#666666" height="175.55555555555554" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9" width="25.14409722222222" x="183.84722222222223" xmlns="http://www.w3.org/2000/svg" y="120.44444444444446"></rect><rect fill="#CCCCCC" height="182.22222222222223" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9" width="25.14409722222222" x="208.99131944444446" xmlns="http://www.w3.org/2000/svg" y="113.77777777777777"></rect><rect fill="#000000" height="105.55555555555556" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9" width="25.14409722222222" x="234.13541666666669" xmlns="http://www.w3.org/2000/svg" y="190.44444444444446"></rect><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(221.5633680555556 315.84)" x="0" xmlns="http://www.w3.org/2000/svg" y="0">Day 1</text><rect fill="#666666" height="100" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9" width="25.14409722222222" x="284.42361111111114" xmlns="http://www.w3.org/2000/svg" y="196"></rect><rect fill="#CCCCCC" height="175.55555555555554" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9" width="25.14409722222222" x="309.56770833333337" xmlns="http://www.w3.org/2000/svg" y="120.44444444444446"></rect><rect fill="#000000" height="122.22222222222223" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9" width="25.14409722222222" x="334.7118055555556" xmlns="http://www.w3.org/2000/svg" y="173.77777777777777"></rect><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(322.1397569444445 315.84)" x="0" xmlns="http://www.w3.org/2000/svg" y="0">Day 2</text><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(271.8515625 24)">Fur Seal REM Sleep on Land </text><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(271.8515625 48)">after an Extended Period </text><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(271.8515625 72)">in Water</text><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="middle" transform="translate(271.8515625 349.67999999999995)">Sleep on land</text><rect fill="none" height="103" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9" width="89.3399658203125" x="162.83001708984375" xmlns="http://www.w3.org/2000/svg" y="366.84000000000003"></rect><rect fill="#666666" height="12" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9" width="12" x="169.83001708984375" xmlns="http://www.w3.org/2000/svg" y="378.84000000000003"></rect><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="top" transform="translate(191.83001708984375 390.84000000000003)"> Seal B</text><rect fill="#CCCCCC" height="12" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9" width="12" x="169.83001708984375" xmlns="http://www.w3.org/2000/svg" y="410.84000000000003"></rect><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="top" transform="translate(191.83001708984375 422.84000000000003)"> Seal A</text><rect fill="#000000" height="12" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9" width="12" x="169.83001708984375" xmlns="http://www.w3.org/2000/svg" y="442.84000000000003"></rect><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="top" transform="translate(191.83001708984375 454.84000000000003)"> Seal C</text></g></svg></figure></p>
<p>Research suggests that REM sleep in animals is homeostatically regulated: animals compensate for periods of REM sleep deprivation by increasing subsequent REM sleep. When on land, fur seals get enough REM sleep, but during the weeks they’re in the water, they get almost none. In a study of fur seals’ sleep habits, researchers recorded the REM sleep (as a percentage of baseline) of fur seals once they had returned to land. They concluded that REM sleep may not be homeostatically regulated in fur seals, citing as evidence the fact that the seals in the study <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the graph to complete the text?</p>$SATQ$, $SATQ$[{"id":"cfb4424e-14cd-4076-8259-4cc492aecbb4","content":"<p>didn&rsquo;t show significantly less REM sleep during the second day after returning to land than they did during the first day.</p>"},{"id":"f27f0268-e81c-4846-afd8-24e9ac611c65","content":"<p>showed no significant differences from one another in baseline levels of REM sleep.</p>"},{"id":"9e886d9e-3d9a-473d-8bdf-a7a372d83d7a","content":"<p>didn&rsquo;t consistently demonstrate a significant increase in REM sleep after their period of deprivation in the water.</p>"},{"id":"c3eb6b15-cee7-4a73-acc9-876dff37c36f","content":"<p>showed no significant difference between REM sleep after returning to land and REM sleep while in the water.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["9e886d9e-3d9a-473d-8bdf-a7a372d83d7a"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. If REM sleep were homeostatically regulated in fur seals, then all the seals would compensate with REM levels significantly over baseline after going weeks without REM. We&rsquo;d also expect the seals to maintain those elevated REM levels for some time. Since seals B and C return very quickly to baseline REM levels, this suggests that REM sleep in fur seals may not be regulated homeostatically. </p><p>Choice A is incorrect. This doesn&rsquo;t support the conclusion. If REM sleep were homeostatically regulated in fur seals, then we&rsquo;d suspect the seals to sustain REM levels well above baseline for a prolonged period in order to compensate for weeks of REM deprivation while in the water. Whether or not there&rsquo;s a reduction in REM sleep from day 1 to day 2 doesn&rsquo;t tell us how REM sleep on those days relates to baseline, which is where our focus should be. Choice B is incorrect. The y-axis of this graph doesn&rsquo;t depict baseline levels of REM sleep, but rather shows REM sleep as a percent of baseline. Choice D is incorrect. The graph doesn&rsquo;t depict REM sleep while in the water for the seals in the study. Additionally, we&rsquo;re told fur seals get no REM sleep while in the water, which is significantly different to the values shown in the graph for after they return to land. </p>$SATQ$, false, 0, $SATQ$OSP-KA-QUA-H009$SATQ$, $SATQ$$SATQ$, $SATQ$d18f6eb4-f58e-4275-b93c-c67bece17bd4$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ccb1ab92","external_id":"e5fb236a-b834-4e49-866c-248c223f4d16","vaultid":"d50bf132-7c01-4162-a3b4-14b4261b28aa","uId":"1aeb7df0-26d4-4493-b2f6-55cf768a0a8b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p><figure class=\"image\"><svg height=\"480.84\" viewbox=\"0 0 400 480.84\" width=\"400\" xmlns=\"http://www.w3.org/2000/svg\"><g data-name=\"Layer 1\" id=\"ed420550-79eb-48d4-af01-cd27cdd08afd\"><defs>\n<pattern height=\"100\" id=\"bar4\" patterntransform=\"rotate(50)\" patternunits=\"userSpaceOnUse\" width=\"10\" x=\"0\" y=\"0\">\n<rect fill=\"#CDCDCD\" height=\"100\" width=\"5\" x=\"0\" y=\"0\"></rect>\n<rect fill=\"#444444\" height=\"100\" width=\"5\" x=\"5\" y=\"0\"></rect>\n</pattern>\n</defs><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"158.703125\" x2=\"385\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"96\" y2=\"96\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"152.703125\" x2=\"164.703125\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"96\" y2=\"96\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(146.703125 102)\">180</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"158.703125\" x2=\"385\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"118.22222222222223\" y2=\"118.22222222222223\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"152.703125\" x2=\"164.703125\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"118.22222222222223\" y2=\"118.22222222222223\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(146.703125 124.22222222222223)\">160</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"158.703125\" x2=\"385\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"140.44444444444446\" y2=\"140.44444444444446\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"152.703125\" x2=\"164.703125\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"140.44444444444446\" y2=\"140.44444444444446\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(146.703125 146.44444444444446)\">140</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"158.703125\" x2=\"385\" xm